// Package pool provides a generic object pool for resettable types,
// built on top of sync.Pool.
//
// Users pass a factory to New and type pool.Pool[T] with any T whose
// pointer form has a Reset method, such as the structs generated by
// cmd/reset. Put resets an object before handing it back, so a dirty
// object never survives inside the pool; Get therefore always yields
// an object whose state was cleared when it was last released.
//
// Like sync.Pool itself, the pool keeps no hard references: cached
// objects may be silently discarded by the garbage collector at any
// time, which is why a factory is required.
package pool

import "sync"

// Resettable is the constraint for pooled types: the value stored in
// a Pool must be a pointer whose type declares Reset().
type Resettable interface {
	Reset()
}

// Pool is a concurrency-safe container of reusable objects of one
// concrete type T.
type Pool[T Resettable] struct {
	sync.Pool
}

// New returns a Pool backed by the given factory. The factory is
// invoked whenever the pool is empty, so it must produce a fully
// usable (not just zero) object of T.
func New[T Resettable](create func() T) *Pool[T] {
	return &Pool[T]{
		Pool: sync.Pool{New: func() any { return create() }},
	}
}

// Get returns an object from the pool, constructing a fresh one
// through the factory when the pool is empty.
func (p *Pool[T]) Get() T {
	return p.Pool.Get().(T)
}

// Put hands an object back to the pool after resetting its state.
func (p *Pool[T]) Put(x T) {
	x.Reset()
	p.Pool.Put(x)
}
